void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord.xy / u_resolution.xy;
  float t = u_time * u_speed * 1.5;
  vec2 st = uv * vec2(40.0, 20.0);
  float col_idx = floor(st.x);
  float drop_speed = 3.0 + sin(col_idx * 133.7) * 2.0;
  float row_y = fract(st.y + t * drop_speed + sin(col_idx * 99.1));
  float char_head = smoothstep(0.95, 1.0, row_y);
  float char_tail = pow(row_y, 3.5);
  float audio_boost = 1.0 + (u_audio_bass * 1.5);
  vec3 green_color = u_color2 * (char_tail * 1.2 + char_head * 2.0) * u_intensity * audio_boost;
  vec3 white_core = vec3(1.0) * char_head * 1.8;
  fragColor = vec4(green_color + white_core, 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = (fragCoord.xy - 0.5 * u_resolution.xy) / u_resolution.y;
  float t = u_time * u_speed;
  vec3 col = vec3(0.02, 0.0, 0.05);
  if (uv.y < 0.0) {
    float depth = -0.35 / (uv.y - 0.02);
    vec2 grid_uv = vec2(uv.x * depth, depth + t * 2.0);
    vec2 grid = abs(fract(grid_uv - 0.5) - 0.5) / fwidth(grid_uv);
    float line = min(grid.x, grid.y);
    float c = 1.0 - min(line, 1.0);
    float bass_glow = 1.0 + u_audio_bass * 2.0;
    col += u_color2 * c * exp(-depth * 0.08) * u_intensity * bass_glow;
  } else {
    vec2 sun_uv = uv - vec2(0.0, 0.08);
    float dist = length(sun_uv);
    if (dist < 0.22) {
      float sun_stripes = step(0.025, fract(sun_uv.y * 18.0 - t * 0.2));
      vec3 sun_col = mix(u_color2, u_accent, (sun_uv.y + 0.22) / 0.44);
      col = mix(col, sun_col * 1.5, sun_stripes);
    }
  }
  fragColor = vec4(col, 1.0);
}

