window.PomodoroZenFlowWidget = (function() {
  let seconds = 25 * 60;
  let timer = null;
  return {
    init: function(el) {
      const display = el.querySelector('#pomo-time-display');
      const btn = el.querySelector('#pomo-toggle-btn');
      btn?.addEventListener('click', () => {
        if (timer) {
          clearInterval(timer);
          timer = null;
          btn.textContent = 'START';
        } else {
          btn.textContent = 'PAUSE';
          timer = setInterval(() => {
            if (seconds > 0) {
              seconds--;
              const m = String(Math.floor(seconds / 60)).padStart(2, '0');
              const s = String(seconds % 60).padStart(2, '0');
              if (display) display.textContent = `${m}:${s}`;
            } else {
              clearInterval(timer);
              timer = null;
              btn.textContent = 'DONE';
            }
          }, 1000);
        }
      });
    }
  };
})();

