window.GitHubActivityWidget = (function() {
  return {
    init: function(el) {
      const grid = el.querySelector('#gh-heatmap-grid');
      if (!grid || grid.children.length > 0) return;
      for (let i = 0; i < 28; i++) {
        const cell = document.createElement('div');
        const level = Math.random() > 0.35 ? Math.floor(Math.random() * 4) + 1 : 0;
        cell.className = 'gh-cell' + (level > 0 ? ' l' + level : '');
        grid.appendChild(cell);
      }
    }
  };
})();
